text:
{
  "status": "AUTHORIZED_UNIQUE",
  "coverage": [
    {
      "text": "那个，",
      "role": "CONTEXT",
      "explanation": "Discourse filler before the command; it introduces no action, parameter, reference or order and does not alter authorization."
    },
    {
      "text": "先",
      "role": "RELATION",
      "explanation": "Marks the following stand as the first action in the execution order."
    },
    {
      "text": "站，",
      "role": "ACTION",
      "explanation": "Requests the stand skill once for the implicit robot; the comma is separation and adds no execution."
    },
    {
      "text": "时间2秒。",
      "role": "QUANTITY",
      "explanation": "Specifies the duration for the immediately preceding stand as 2 seconds; this is positive and within the stand duration limit."
    },
    {
      "text": "对，",
      "role": "EDIT",
      "explanation": "Affirmation of the preceding duration instruction; it does not replace or add any action or parameter."
    },
    {
      "text": "就2秒；",
      "role": "EDIT",
      "explanation": "Reasserts that the stand duration is exactly 2 seconds and introduces no repetition, new action, or unresolved value."
    },
    {
      "text": "接着",
      "role": "RELATION",
      "explanation": "Connects the next walk_forward action as occurring after the completed stand action in the single linear sequence."
    },
    {
      "text": "往前走",
      "role": "ACTION",
      "explanation": "Requests one walk_forward action by the same implicit robot; no direction parameter beyond forward is used."
    },
    {
      "text": "4米，",
      "role": "QUANTITY",
      "explanation": "Specifies the walk_forward distance as 4 meters; the trailing comma separates but does not change the quantity."
    },
